  /**
   * @method
   * @name cryptomus#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see https://doc.cryptomus.com/personal/converts/balance
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<std::any>
  fetchBalance(std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any request = ccxt::dict{};
                        std::any response = awaitValue(
                            this->privateGetV2UserApiExchangeAccountBalance(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "result": [
                        //             {
                        //                 "ticker": "AVAX",
                        //                 "available": "0.00000000",
                        //                 "held": "0.00000000"
                        //             }
                        //         ]
                        //     }
                        //
                        std::any result = this->safeList(
                            response, std::string("result"), ccxt::list{});
                        return this->parseBalance(result);
                      })
        .share();
  }

  std::any parseBalance(std::any balance) override {
    //
    //     {
    //         "ticker": "AVAX",
    //         "available": "0.00000000",
    //         "held": "0.00000000"
    //     }
    //
    std::any result = ccxt::dict{
        {std::string("info"), balance},
    };
    for (std::any i = 0; isLessThan(i, getArrayLength(balance));
         postFixIncrement(i)) {
      std::any balanceEntry = ::getValue(balance, i);
      std::any currencyId =
          this->safeString(balanceEntry, std::string("ticker"));
      std::any code = this->safeCurrencyCode(currencyId);
      std::any account = this->account();
      ::setValue(account, std::string("free"),
                 this->safeString(balanceEntry, std::string("available")));
      ::setValue(account, std::string("used"),
                 this->safeString(balanceEntry, std::string("held")));
      if (isTrue(!isEqual(code, std::any{}))) {
        ::setValue(result, code, account);
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name cryptomus#createOrder
   * @description create a trade order
   * @see https://doc.cryptomus.com/personal/exchange/market-order-creation
   * @see https://doc.cryptomus.com/personal/exchange/limit-order-creation
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit' or for spot
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of you want to trade in units of the base
   * currency
   * @param {float} [price] the price that the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders (only for limit
   * orders)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {float} [params.cost] *market buy only* the quote quantity that can
   * be used as an alternative for the amount
   * @param {string} [params.clientOrderId] a unique identifier for the order
   * (optional)
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  createOrder(std::any symbol, std::any type, std::any side, std::any amount,
              std::any price = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> std::any {
                if (isTrue(isEqual(this->markets, std::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                std::any market = this->market(symbol);
                std::any request = ccxt::dict{
                    {std::string("market"),
                     ::getValue(market, std::string("id"))},
                    {std::string("direction"), side},
                    {std::string("tag"), std::string("ccxt")},
                };
                std::any clientOrderId =
                    this->safeString(params, std::string("clientOrderId"));
                if (isTrue(!isEqual(clientOrderId, std::any{}))) {
                  params = this->omit(params, std::string("clientOrderId"));
                  ::setValue(request, std::string("client_order_id"),
                             clientOrderId);
                }
                std::any sideBuy = isEqual(side, std::string("buy"));
                std::any amountToString = this->numberToString(amount);
                std::any priceToString = this->numberToString(price);
                std::any cost = std::any{};
                std::any costparamsVariable =
                    this->handleParamString(params, std::string("cost"));
                cost = ::getValue(costparamsVariable, 0);
                params = ::getValue(costparamsVariable, 1);
                std::any response = std::any{};
                if (isTrue(isEqual(type, std::string("market")))) {
                  if (isTrue(sideBuy)) {
                    std::any createMarketBuyOrderRequiresPrice = true;
                    std::any createMarketBuyOrderRequiresPriceparamsVariable =
                        this->handleOptionAndParams(
                            params, std::string("createOrder"),
                            std::string("createMarketBuyOrderRequiresPrice"),
                            true);
                    createMarketBuyOrderRequiresPrice = ::getValue(
                        createMarketBuyOrderRequiresPriceparamsVariable, 0);
                    params = ::getValue(
                        createMarketBuyOrderRequiresPriceparamsVariable, 1);
                    if (isTrue(createMarketBuyOrderRequiresPrice)) {
                      if (isTrue(isTrue((isEqual(price, std::any{}))) &&
                                 isTrue((isEqual(cost, std::any{}))))) {
                        throw InvalidOrder(toString(add(
                            this->id,
                            std::string(
                                " createOrder() requires the price argument "
                                "for market buy orders to calculate the total "
                                "cost to spend (amount * price), alternatively "
                                "set the createMarketBuyOrderRequiresPrice "
                                "option of param to false and pass the cost to "
                                "spend in the amount argument"))));
                      } else if (isTrue(isEqual(cost, std::any{}))) {
                        cost = ccxt::Precise::stringMul(amountToString,
                                                        priceToString);
                      }
                    } else {
                      cost = (isTrue((isTrue(!isEqual(cost, std::any{})) &&
                                      isTrue(!isEqual(cost, std::string("")))))
                                  ? std::any(cost)
                                  : std::any(amountToString));
                    }
                    ::setValue(request, std::string("value"), cost);
                  } else {
                    ::setValue(request, std::string("quantity"),
                               amountToString);
                  }
                  response =
                      awaitValue(this->privatePostV2UserApiExchangeOrdersMarket(
                          this->extend(request, params)));
                } else if (isTrue(isEqual(type, std::string("limit")))) {
                  if (isTrue(isEqual(price, std::any{}))) {
                    throw ArgumentsRequired(toString(
                        add(add(add(this->id,
                                    std::string(" createOrder() requires a "
                                                "price parameter for a ")),
                                type),
                            std::string(" order"))));
                  }
                  ::setValue(request, std::string("quantity"), amountToString);
                  ::setValue(request, std::string("price"), price);
                  response =
                      awaitValue(this->privatePostV2UserApiExchangeOrders(
                          this->extend(request, params)));
                } else {
                  throw ArgumentsRequired(toString(add(
                      this->id, std::string(" createOrder() requires a type "
                                            "parameter (limit or market)"))));
                }
                //
                //     {
                //         "order_id": "01JEXAFCCC5ZVJPZAAHHDKQBMG"
                //     }
                //
                return this->parseOrder(response, market);
              })
            .share();
  }

  /**
   * @method
   * @name cryptomus#cancelOrder
   * @description cancels an open limit order
   * @see https://doc.cryptomus.com/personal/exchange/limit-order-cancellation
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * (not used in cryptomus)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  cancelOrder(std::any id, std::any symbol = std::any{},
              std::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> std::any {
                        if (isTrue(isEqual(this->markets, std::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        std::any request = ccxt::dict{};
                        ::setValue(request, std::string("orderId"), id);
                        std::any response = awaitValue(
                            this->privateDeleteV2UserApiExchangeOrdersOrderId(
                                this->extend(request, params)));
                        //
                        //     {
                        //         "success": true
                        //     }
                        //
                        return this->safeOrder(ccxt::dict{
                            {std::string("info"), response},
                        });
                      })
        .share();
  }

  /**
   * @method
   * @name cryptomus#fetchOrders
   * @description fetches information on multiple orders made by the user
   * @see
   * https://doc.cryptomus.com/personal/exchange/history-of-completed-orders
   * @param {string} symbol unified market symbol of the market orders were made
   * in (not used in cryptomus)
   * @param {int} [since] the earliest time in ms to fetch orders for (not used
   * in cryptomus)
   * @param {int} [limit] the maximum number of order structures to retrieve
   * (not used in cryptomus)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.direction] order direction 'buy' or 'sell'
   * @param {string} [params.order_id] order id
   * @param {string} [params.client_order_id] client order id
   * @param {string} [params.limit] A special parameter that sets the maximum
   * number of records the request will return
   * @param {string} [params.offset] A special parameter that sets the number of
   * records from the beginning of the list
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any> fetchCanceledAndClosedOrders(
      std::any symbol = std::any{}, std::any since = std::any{},
      std::any limit = std::any{}, std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any request = ccxt::dict{};
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("market"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(limit, std::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 std::any response =
                     awaitValue(this->privateGetV2UserApiExchangeOrdersHistory(
                         this->extend(request, params)));
                 //
                 //     {
                 //         "result": [
                 //             {
                 //                 "id": "01JEXAPY04JDFBVFC2D23BCKMK",
                 //                 "type": "market",
                 //                 "direction": "sell",
                 //                 "symbol": "TRX_USDT",
                 //                 "quantity": "67.5400000000000000",
                 //                 "filledQuantity": "67.5400000000000000",
                 //                 "filledValue": "20.0053480000000000",
                 //                 "state": "completed",
                 //                 "internalState": "filled",
                 //                 "createdAt": "2024-12-12 11:40:19",
                 //                 "finishedAt": "2024-12-12 11:40:21",
                 //                 "deal": {
                 //                     "id": "01JEXAPZ9C9TWENPFZJASZ1YD2",
                 //                     "state": "completed",
                 //                     "createdAt": "2024-12-12 11:40:21",
                 //                     "completedAt": "2024-12-12 11:40:21",
                 //                     "averageFilledPrice":
                 //                     "0.2962000000000000", "transactions": [
                 //                         {
                 //                             "id":
                 //                             "01JEXAPZ9C9TWENPFZJASZ1YD3",
                 //                             "tradeRole": "taker",
                 //                             "filledPrice":
                 //                             "0.2962000000000000",
                 //                             "filledQuantity":
                 //                             "67.5400000000000000",
                 //                             "filledValue":
                 //                             "20.0053480000000000", "fee":
                 //                             "0.0000000000000000",
                 //                             "feeCurrency": "USDT",
                 //                             "committedAt": "2024-12-12
                 //                             11:40:21"
                 //                         }
                 //                     ]
                 //                 }
                 //             },
                 //             ...
                 //         ]
                 //     }
                 //
                 std::any result = this->safeList(
                     response, std::string("result"), ccxt::list{});
                 std::any orders = ccxt::list{};
                 for (std::any i = 0; isLessThan(i, getArrayLength(result));
                      postFixIncrement(i)) {
                   std::any order = ::getValue(result, i);
                   arrayPush(orders, this->parseOrder(order, market));
                 }
                 return orders;
               })
        .share();
  }

